import {all, get, put, remove, clear, dataDump, importDump, newId} from './db.js';
import {SEED} from './seed.js';
import {estimatePlan, ACTIVITY, EMPTY_PROFILE} from './goals.js';
import {estimateRestaurantMeal, genericSearchText} from './smart-food.js';
import {POPULAR_FOODS,rankFoodMatches,interpretFoodQuery} from './food-search.js';
import {round,n,totals,scale,parseAI,offToFood,findProducts,findUSDA,parsePublishedFacts,findBarcode,dateKey,shiftDate,prettyDate} from './nutrition.js';

const MEALS=['Breakfast','Lunch','Dinner','Snack'];
const DEFAULTS={calorieGoal:2200,proteinGoal:155,carbsGoal:230,fatGoal:70,waterGoal:2400,fastHours:16,exerciseBudget:false,theme:'dark',unit:'lb'};
const S={view:'dashboard',date:dateKey(),settings:{...DEFAULTS},profile:{...EMPTY_PROFILE},profileSetup:false,rows:{},modal:null,tab:'search',meal:'Lunch',query:'',online:[],food:null,grams:100,photo:null,aiFood:null,recipeIngredients:[],recipeQuery:'',recipeName:'',recipeServings:2,fastAt:null,filters:'all',busy:false,description:'',factsText:'',factsName:'',searchStatus:'',smartFood:null,smartSearchTried:false,searchId:0,productTimer:null,productSearchSeq:0};
const $=(sel)=>document.querySelector(sel);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount=(v,d=0)=>Number(n(v)).toLocaleString('en-US',{maximumFractionDigits:d});
const tabIcon={dashboard:'⌂',log:'▤',goals:'◎',foods:'▦',plan:'▦',profile:'♙',settings:'⚙'};
const NAV=[['dashboard','Dashboard'],['log','Log'],['goals','Goals'],['profile','Profile']];
const navActive=id=>S.view===id || (id==='profile' && ['foods','plan','settings'].includes(S.view));
const uiIcon=(name)=>{
 const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',log:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21c0-5 3-7 8-7s8 2 8 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',foods:'<path d="M4 4h16v16H4zM8 9h8M8 13h8M8 17h4"/>',plan:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4M8 14h3M14 14h3"/>'};
 return `<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${paths[name]||paths.dashboard}</svg>`;
};
const today=()=>dateKey();
const inDate=(rows,date)=>rows.filter(x=>x.date===date);
const records=table=>S.rows[table]||[];
const stats=(date=S.date)=>totals(inDate(records('logs'),date));
const exercises=(date=S.date)=>totals(inDate(records('workouts'),date));
const safeGoal=(v,fallback=1)=>Math.max(1,n(v)||fallback);
const getWater=(date=S.date)=>records('water').find(r=>r.date===date)?.ml||0;
const saveSettings=async()=>put('meta',{id:'settings',value:S.settings});
let toastTimeout, stream=null, scanRAF=null;
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),2900);}
function download(filename,content,mime){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function refresh(){for(const key of ['logs','water','weights','workouts','foods','recipes','plans'])S.rows[key]=await all(key);render();}
const btn=(action,label,variant='secondary',extra='')=>`<button class="btn ${variant} smallbtn" data-action="${action}" ${extra}>${label}</button>`;
function header(){return `<header class="topbar"><div class="brand"><span class="brand-icon">◒</span><div><div class="brand-name">PlatePilot<span style="color:var(--accent)">.</span></div><div class="brand-tag">Your nutrition, your way</div></div></div><div class="top-actions"><span class="pill"><span class="dot"></span> Saved on this device</span><button class="icon-btn profile-avatar" title="Profile and plans" data-action="nav" data-view="profile" aria-label="Open profile">${uiIcon('profile')}</button></div></header><nav class="desktop-nav">${navs()}</nav>`;}
function navs(){return [...NAV.slice(0,2),['quick','Add food'],...NAV.slice(2)].map(([id,text])=>id==='quick'?`<button class="nav-tab nav-plus" data-action="open-quick" aria-label="Quick log">${uiIcon('plus')} ${text}</button>`:`<button class="nav-tab ${navActive(id)?'active':''}" data-action="nav" data-view="${id}">${uiIcon(id)} ${text}</button>`).join('');}
function bottomNav(){const items=[...NAV.slice(0,2),['quick','Add'],...NAV.slice(2)];return `<nav class="mobile-nav" aria-label="Main navigation">${items.map(([id,label])=>id==='quick'?`<button class="mobile-item mobile-add" data-action="open-quick" aria-label="Add food or activity"><span class="add-circle">${uiIcon('plus')}</span><span class="add-label">Add</span></button>`:`<button class="mobile-item ${navActive(id)?'active':''}" data-action="nav" data-view="${id}" ${navActive(id)?'aria-current="page"':''}><span class="sym">${uiIcon(id)}</span><span>${label}</span></button>`).join('')}</nav>`;}
function pageHeader(title,kicker,sub,withDate=false){return `<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1 class="page-title">${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${withDate?`<div class="date-switch"><button class="icon-btn" data-action="shift-date" data-days="-1" aria-label="Previous day">‹</button><div class="date-label">${prettyDate(S.date,{month:'short',day:'numeric'})}<br><span class="tiny">${prettyDate(S.date,{weekday:'short'})}</span></div><button class="icon-btn" data-action="shift-date" data-days="1" aria-label="Next day">›</button></div>`:''}</div>`;}
function progress(val,target,cl=''){return `<div class="progress ${cl}"><span style="width:${Math.max(0,Math.min(100,100*n(val)/safeGoal(target))).toFixed(1)}%"></span></div>`;}
function render(){document.body.classList.toggle('theme-light',S.settings.theme==='light');$('#app').innerHTML=`<div class="app-shell">${header()}<main>${S.view==='dashboard'?dashboardPage():S.view==='log'?todayPage():S.view==='goals'?trendsPage():S.view==='foods'?foodsPage():S.view==='plan'?planPage():S.view==='profile'?profilePage():settingsPage()}</main></div>${bottomNav()}`;renderModal();if(S.view==='profile')updateProfilePreview();}
function compactBudget(){const total=stats();const workoutCal=inDate(records('workouts'),S.date).reduce((a,r)=>a+n(r.calories),0);const goal=S.settings.calorieGoal+(S.settings.exerciseBudget?workoutCal:0);const left=goal-total.calories;return `<section class="card log-budget"><div class="mini-budget"><div><span>Budget</span><strong>${amount(goal)}</strong></div><span class="budget-symbol">−</span><div><span>Food</span><strong>${amount(total.calories)}</strong></div><span class="budget-symbol">=</span><div><span>${left>=0?'Left':'Over'}</span><strong class="${left<0?'over-goal':'under-goal'}">${amount(Math.abs(left))}</strong></div></div><div class="log-macro-line"><span>Protein ${amount(total.protein)} / ${amount(S.settings.proteinGoal)} g</span><span>Carbs ${amount(total.carbs)} / ${amount(S.settings.carbsGoal)} g</span><span>Fat ${amount(total.fat)} / ${amount(S.settings.fatGoal)} g</span></div></section>`;}
function dashboardPage(){const t=stats();const activity=inDate(records('workouts'),S.date).reduce((a,r)=>a+n(r.calories),0);const allowed=S.settings.calorieGoal+(S.settings.exerciseBudget?activity:0);const left=allowed-t.calories;const used=Math.max(0,Math.min(100,100*t.calories/safeGoal(allowed)));const last=inDate(records('logs'),S.date);const weights=[...records('weights')].sort((a,b)=>b.date.localeCompare(a.date));return `${pageHeader('Dashboard','DAILY OVERVIEW','Everything you need for today, at a glance.',true)}
${profileBanner()}
<div class="summary-grid"><section class="card cal-card"><div class="card-hd"><h2>Calories</h2><button class="profile-link" data-action="nav" data-view="log">Open food log →</button></div><div class="cal-body"><div class="cal-ring" style="--progress:${used.toFixed(1)}%"><div class="ring-inner"><strong>${amount(Math.abs(left))}</strong><span>${left>=0?'remaining':'over goal'}</span></div></div><div class="cal-stats"><div class="stat-row"><span class="stat-name">Budget</span><strong>${amount(allowed)}</strong></div><div class="stat-row"><span class="stat-name">Food</span><strong>${amount(t.calories)}</strong></div><div class="stat-row"><span class="stat-name">Exercise</span><strong>${amount(activity)}</strong></div></div></div><p class="subtle-note">${last.length} food entr${last.length===1?'y':'ies'} today. ${S.settings.exerciseBudget?'Activity calories are included in your budget.':'Activity calories are not added to your budget.'}</p></section>
<section class="card macro-card"><div class="card-hd"><h2>Your macros</h2><button class="profile-link" data-action="nav" data-view="goals">View goals →</button></div><div class="macro-list">${[['Protein','protein','proteinGoal',''],['Carbs','carbs','carbsGoal','blue'],['Fat','fat','fatGoal','pink']].map(([label,key,goal,c])=>`<div><div class="macro-label"><b>${label}</b><span>${amount(t[key],1)} / ${amount(S.settings[goal])} g</span></div>${progress(t[key],S.settings[goal],c)}</div>`).join('')}</div><p class="subtle-note">Fiber logged: ${amount(t.fiber,1)} g</p></section></div>
<section class="card dashboard-launch"><div class="card-hd"><h2>Quick access</h2><span class="small">Your everyday actions</span></div><div class="launch-grid"><button class="launch-tile" data-action="nav" data-view="log"><span class="tile-icon">${uiIcon('log')}</span><strong>Food log</strong><small>Breakfast, lunch, dinner and snacks</small></button><button class="launch-tile" data-action="open-photo"><span class="tile-icon">📷</span><strong>Photo estimate</strong><small>Apple Intelligence Shortcut</small></button><button class="launch-tile" data-action="nav" data-view="foods"><span class="tile-icon">${uiIcon('foods')}</span><strong>My foods & recipes</strong><small>Saved foods and homemade meals</small></button><button class="launch-tile" data-action="nav" data-view="plan"><span class="tile-icon">${uiIcon('plan')}</span><strong>Meal planner</strong><small>Plan ahead and repeat meals</small></button></div></section>
<div class="two-col dashboard-bottom"><div class="left-stack"><section class="card"><div class="card-hd"><h2>Today’s meals</h2>${btn('open-add','＋ Log food','')}</div>${MEALS.map(meal=>`<div class="dash-meal"><span>${meal}</span><strong>${amount(totals(last.filter(r=>r.meal===meal)).calories)} kcal</strong></div>`).join('')}<button class="btn secondary full" data-action="nav" data-view="log">Go to full diary →</button></section></div><div class="right-stack"><section class="card"><div class="card-hd"><h2>Water</h2><span class="small">${amount(S.settings.waterGoal)} mL goal</span></div>${progress(getWater(),S.settings.waterGoal,'blue')}<div class="water-control"><div><strong>${amount(getWater())}</strong> <small>mL</small></div><span class="spacer"></span><button class="water-btn" data-action="water" data-delta="-250" aria-label="Subtract 250 milliliters">−</button><button class="water-btn" data-action="water" data-delta="250" aria-label="Add 250 milliliters">+</button></div></section><section class="card"><div class="card-hd"><h2>Progress</h2><button class="profile-link" data-action="nav" data-view="goals">All goals →</button></div><div class="dash-meal"><span>Latest weight</span><strong>${weights.length?`${amount(weights[0].lb,1)} lb`:'Not logged'}</strong></div>${btn('open-weight','＋ Weigh in','secondary')}<div class="divider"></div><div class="dash-meal"><span>Daily target</span><strong>${amount(S.settings.calorieGoal)} kcal</strong></div><button class="profile-link" data-action="nav" data-view="profile">Update your plan →</button></section></div></div>`;}
function todayPage(){const workoutCal=inDate(records('workouts'),S.date).reduce((a,r)=>a+n(r.calories),0);return `${pageHeader('Food log','YOUR DAILY DIARY','Log meals, water, and exercise with minimal taps.',true)}
${!S.profileSetup?profileBanner():''}${compactBudget()}
<div class="two-col"><div class="left-stack"><section class="card diary-card"><div class="card-hd"><div><h2>Food diary</h2><p class="section-sub">${prettyDate(S.date,{weekday:'long',month:'short',day:'numeric'})}</p></div>${btn('open-add','＋ Add food','')}</div>${MEALS.map(meal=>mealBlock(meal)).join('')}</section></div><div class="right-stack"><section class="card"><div class="card-hd"><h2>Fast logging</h2></div><div class="quick-row"><button data-action="open-photo" class="quick-action"><span class="emoji">📷</span><b>Snap It</b><span>AI photo entry</span></button><button data-action="open-barcode" class="quick-action"><span class="emoji">▥</span><b>Scan It</b><span>Barcode lookup</span></button></div><div style="margin-top:10px">${btn('open-describe','🎙 Describe or dictate a meal','secondary','style="width:100%"')}</div></section><section class="card"><div class="card-hd"><h2>Water</h2><span class="small">Goal ${amount(S.settings.waterGoal)} mL</span></div>${progress(getWater(),S.settings.waterGoal,'blue')}<div class="water-control"><div><strong>${amount(getWater())}</strong> <small>mL</small></div><span class="spacer"></span><button class="water-btn" data-action="water" data-delta="-250" aria-label="Subtract 250 milliliters">−</button><button class="water-btn" data-action="water" data-delta="250" aria-label="Add 250 milliliters">+</button></div></section><section class="card"><div class="card-hd"><h2>Exercise</h2>${btn('open-workout','＋ Add exercise')}</div>${inDate(records('workouts'),S.date).map(w=>`<div class="fitness-line"><span>⚡</span><div>${esc(w.name)}<div class="tiny">${amount(w.minutes)} min</div></div><small>${amount(w.calories)} kcal</small><button class="trash" data-action="delete-workout" data-id="${esc(w.id)}" aria-label="Remove workout">×</button></div>`).join('')||'<p class="note">No exercise logged yet. WHOOP sync is not automatic.</p>'}<p class="subtle-note">${amount(workoutCal)} activity kcal recorded. ${S.settings.exerciseBudget?'Counted toward budget.':'Not added to budget to avoid double counting.'}</p></section><section class="card"><div class="card-hd"><h2>Fasting</h2><span class="small">${amount(S.settings.fastHours)}h target</span></div>${fastingCard()}</section></div></div>`;}
function mealBlock(meal){const rows=inDate(records('logs'),S.date).filter(r=>r.meal===meal).sort((a,b)=>(a.createdAt||'').localeCompare(b.createdAt||''));return `<div class="meal-head"><span class="meal-name">${meal}</span><div style="display:flex;align-items:center;gap:10px"><span class="meal-total">${amount(totals(rows).calories)} kcal</span><button class="meal-add" data-action="open-add" data-meal="${meal}">＋ Add</button></div></div>${rows.length?rows.map(r=>`<div class="log-row"><div class="food-mark">${r.photo?`<img style="width:37px;height:37px;object-fit:cover;border-radius:11px" src="${r.photo}" alt="">`:'◦'}</div><div class="food-info"><div class="food-name">${esc(r.name)}</div><div class="food-detail">${r.grams?amount(r.grams)+' g · ':''}P ${amount(r.protein,1)} · C ${amount(r.carbs,1)} · F ${amount(r.fat,1)}${r.source?' · '+esc(r.source):''}</div></div><div class="kcal">${amount(r.calories)} <span class="tiny">kcal</span></div><button class="trash" data-action="delete-log" data-id="${esc(r.id)}" aria-label="Delete ${esc(r.name)}">×</button></div>`).join(''):`<div class="empty-meal">Nothing logged yet</div>`}`;}
function fastingCard(){if(!S.fastAt)return `<p class="note">Track your eating window with a simple timer.</p>${btn('start-fast','Start fasting timer','')}`;const passed=(Date.now()-new Date(S.fastAt).getTime())/3600000;const left=Math.max(0,S.settings.fastHours-passed);return `<div style="font-size:29px;font-weight:800">${amount(passed,1)} <span class="small">hours elapsed</span></div>${progress(passed,S.settings.fastHours)}<p class="note">${left?`${amount(left,1)} hours until your ${S.settings.fastHours}h goal`:'Target reached!'} · Started ${new Date(S.fastAt).toLocaleString()}</p>${btn('stop-fast','End fast','secondary')}`;}
function foodsPage(){const recipes=records('recipes');const foods=records('foods');return `${pageHeader('Food library','YOUR PERSONAL FOODS','Find foods, save favorites and build your own meals.')}
<div class="two-col"><div class="left-stack"><section class="card"><div class="card-hd"><h2>Food search</h2>${btn('open-add','＋ Log food','')}</div><div class="banner"><b>Offline food reference</b>More than 60 common food estimates available even without internet. Online branded food search is available in the Add Food screen when connected.</div><div style="height:12px"></div><input id="library-search" class="searchbox" placeholder="Search your foods and common ingredients…" autocomplete="off"><div id="library-results">${foodResults(SEED.slice(0,8),'favorite')}</div></section>
<section class="card"><div class="card-hd"><h2>My saved foods</h2>${btn('open-manual','＋ Custom food')}</div>${foods.length?foods.map(f=>`<div class="recipe-row"><div><strong>${esc(f.name)}</strong><small>${amount(f.calories)} kcal / 100 g · ${esc(f.source||'Your food')}</small></div><div style="display:flex;gap:6px">${btn('log-saved','Log','secondary',`data-id="${esc(f.id)}"`)}<button class="trash" data-action="delete-food" data-id="${esc(f.id)}" aria-label="Delete food">×</button></div></div>`).join(''):`<div class="no-items">Foods you save for reuse show up here.</div>`}</section></div>
<div class="right-stack"><section class="card"><div class="card-hd"><h2>My recipes</h2>${btn('open-recipe','＋ Recipe')}</div>${recipes.length?recipes.map(r=>`<div class="recipe-row"><div><strong>${esc(r.name)}</strong><small>${amount(r.calories)} kcal / serving · ${r.ingredients?.length||0} ingredients</small></div><div style="display:flex;gap:6px">${btn('log-recipe','Log','secondary',`data-id="${esc(r.id)}"`)}<button class="trash" data-action="delete-recipe" data-id="${esc(r.id)}" aria-label="Delete recipe">×</button></div></div>`).join(''):`<div class="no-items">Save recipes to track complete homemade meals in one tap.</div>`}</section><section class="card"><div class="card-hd"><h2>Quick tools</h2></div><div class="stack">${btn('open-barcode','▥ Look up a barcode')}${btn('open-photo','📷 AI food estimate')}${btn('open-manual','＋ Add food from nutrition label')}</div></section></div></div>`;}
function foodResults(arr,action='select-food'){
 return arr.length?arr.slice(0,30).map(f=>{const g=f.servingG||100;const v=scale(f,g);const portion=f.servingLabel||'100 g';return `<div class="food-result"><div class="food-mark">◦</div><div class="result-title"><b>${esc(f.name)}</b><small>${esc(f.brand||f.source||'Food')} · ${esc(portion)}${f.verifiedServing?' · Official label':''}</small><small>P ${amount(v.protein,1)}g · C ${amount(v.carbs,1)}g · F ${amount(v.fat,1)}g per serving</small></div><div class="result-right"><strong>${amount(v.calories)} <span class="tiny">kcal</span></strong><button class="round-add" data-action="${action}" data-id="${esc(f.id)}" aria-label="Select ${esc(f.name)}">+</button></div></div>`;}).join(''):`<div class="no-items">No matching food yet. Try Search more online or create your own food.</div>`;
}
function trendsPage(){const days=Array.from({length:7},(_,i)=>shiftDate(S.date,i-6));const vals=days.map(d=>({day:d,...stats(d)}));const avg=vals.reduce((sum,r)=>sum+r.calories,0)/7;const max=Math.max(S.settings.calorieGoal,...vals.map(r=>r.calories),1);const weights=[...records('weights')].sort((a,b)=>b.date.localeCompare(a.date));const daylogs=records('logs').filter(x=>days.includes(x.date)).length;
return `${pageHeader('Goals','YOUR WEIGHT & NUTRITION TARGETS','Monitor progress and keep your plan on track.',true)}<section class="card goals-snapshot"><div class="card-hd"><h2>Your daily goals</h2><button class="profile-link" data-action="nav" data-view="profile">Edit plan →</button></div><div class="goal-pills"><span><b>${amount(S.settings.calorieGoal)}</b><small>Calories</small></span><span><b>${amount(S.settings.proteinGoal)}g</b><small>Protein</small></span><span><b>${amount(S.settings.carbsGoal)}g</b><small>Carbs</small></span><span><b>${amount(S.settings.fatGoal)}g</b><small>Fat</small></span></div></section><div class="stats-grid"><div class="info-stat"><small>Daily avg · 7 days</small><strong>${amount(avg)} kcal</strong></div><div class="info-stat"><small>Meals logged · 7 days</small><strong>${daylogs}</strong></div><div class="info-stat"><small>Latest weight</small><strong>${weights.length?`${amount(weights[0].lb,1)} lb`:'—'}</strong></div></div><div style="height:16px"></div><div class="two-col"><div class="left-stack"><section class="card"><div class="card-hd"><h2>Calories by day</h2><span class="small">7 day history</span></div><div class="weekly-bars">${vals.map(r=>`<div class="bar-col"><b>${amount(r.calories)}</b><div class="bar-track"><div class="bar" style="height:${Math.max(3,r.calories/max*140)}px"></div></div><small>${prettyDate(r.day,{weekday:'short'})}</small></div>`).join('')}</div><p class="note">Goal: ${amount(S.settings.calorieGoal)} kcal per day. Empty days are shown as zero, not counted as verified fasting days.</p></section>
<section class="card"><div class="card-hd"><h2>Weekly macro averages</h2></div><div class="macro-list">${[['Protein','protein','proteinGoal',''],['Carbs','carbs','carbsGoal','blue'],['Fat','fat','fatGoal','pink']].map(([label,key,goal,c])=>{const avg=vals.reduce((v,r)=>v+r[key],0)/7;return `<div><div class="macro-label"><b>${label}</b><span>${amount(avg,1)} / ${amount(S.settings[goal])}g</span></div>${progress(avg,S.settings[goal],c)}</div>`;}).join('')}</div></section></div>
<div class="right-stack"><section class="card"><div class="card-hd"><h2>Weight log</h2>${btn('open-weight','＋ Weigh in','')}</div>${weights.length?`<div class="mini-history">${weights.slice(0,12).map(w=>`<div class="history-row"><span>${prettyDate(w.date,{month:'short',day:'numeric'})}</span><strong>${amount(w.lb,1)} lb</strong><button class="trash" data-action="delete-weight" data-id="${esc(w.id)}">×</button></div>`).join('')}</div>`:`<div class="no-items">Record weight to see your history here.</div>`}</section><section class="card"><div class="card-hd"><h2>Data ownership</h2></div><p class="note">Your food diary stays inside this device’s browser storage. Back it up before switching phones or deleting browser data.</p>${btn('export-json','↓ Back up all data','')}</section></div></div>`;}
function planPage(){const days=Array.from({length:7},(_,i)=>shiftDate(S.date,i));return `${pageHeader('Meal planning','YOUR WEEK AHEAD','Copy a logged day into your plan and log the plan later.',true)}<div class="two-col"><div class="left-stack"><section class="card"><div class="card-hd"><h2>Next seven days</h2><span class="small">Starting ${prettyDate(S.date,{month:'short',day:'numeric'})}</span></div>${days.map(d=>{const p=records('plans').find(x=>x.date===d);return `<div class="planner-day"><div><strong>${prettyDate(d)}</strong><small>${p?`${p.items.length} foods planned · ${amount(totals(p.items).calories)} kcal${p.applied?' · logged':''}`:'Nothing planned yet'}</small></div><div style="display:flex;gap:5px;align-items:center">${p&&!p.applied?btn('apply-plan','Log','',`data-date="${d}"`):''}${btn('plan-copy','Plan','secondary',`data-date="${d}"`)}${p?`<button class="trash" data-action="delete-plan" data-date="${d}" aria-label="Delete plan">×</button>`:''}</div></div>`;}).join('')}</section></div><div class="right-stack"><section class="card"><div class="card-hd"><h2>How planning works</h2></div><div class="banner"><b>Repeat meals in seconds</b>Tap Plan beside a day, choose an existing logged day to copy, and save the plan. Tap Log when ready to add its meals to the food diary.</div><p class="note">Your planned meals never count toward eaten calories until you choose Log.</p></section><section class="card"><div class="card-hd"><h2>Meal ideas</h2></div>${records('recipes').length?records('recipes').slice(0,5).map(r=>`<div class="recipe-row"><div><strong>${esc(r.name)}</strong><small>${amount(r.calories)} kcal/serving</small></div>${btn('log-recipe','Log','secondary',`data-id="${esc(r.id)}"`)}</div>`).join(''):`<p class="note">Create saved recipes in the Foods tab and they'll appear here.</p>`}${btn('open-recipe','＋ Build recipe')}</section></div></div>`;}

function profileBanner(){if(!S.profileSetup)return `<div class="profile-banner setup-banner"><div><strong>Make your nutrition plan personal</strong><p>Choose lose, maintain, or gain weight to calculate your daily calorie and macro goals. Your current diary is safe.</p></div><button class="btn smallbtn" data-action="nav" data-view="profile">Set up profile →</button></div>`;
const label={lose:'Weight loss',maintain:'Maintenance',gain:'Weight gain'}[S.profile.goal]||'Personal';
return `<div class="profile-banner compact-banner"><span>◎ &nbsp; ${label} plan: <strong>${amount(S.settings.calorieGoal)} kcal/day</strong></span><button data-action="nav" data-view="profile" class="profile-link">Edit profile →</button></div>`;}
function profileOptions(name, options, selected){return options.map(([key,label])=>`<option value="${esc(key)}" ${String(selected)===String(key)?'selected':''}>${esc(label)}</option>`).join('');}
function readProfileInput(form){const v=Object.fromEntries(new FormData(form));return {
  age:String(v.age??'').trim(),sex:v.sex||'',heightFt:String(v.heightFt??'').trim(),
  heightIn:String(v.heightIn??'0').trim(),weightLb:String(v.weightLb??'').trim(),
  goalWeightLb:String(v.goalWeightLb??'').trim(),activity:v.activity||'light',
  goal:v.goal||'maintain',pace:v.pace||'0.5',macros:v.macros||'balanced'
};}
function profilePreviewMarkup(plan){const sign=plan.adjustment>0?'+':plan.adjustment<0?'−':'';
return `<div class="plan-result"><p class="eyebrow">YOUR ESTIMATED DAILY BUDGET</p><div class="recommended-cal">${amount(plan.calorieGoal)}<span>kcal/day</span></div><div class="profile-stat-line"><span>Estimated maintenance</span><strong>${amount(plan.maintenance)} kcal</strong></div><div class="profile-stat-line"><span>Adjustment for goal</span><strong>${sign}${amount(Math.abs(plan.adjustment))} kcal</strong></div><div class="profile-stat-line"><span>Resting energy estimate</span><strong>${amount(plan.resting)} kcal</strong></div><div class="divider"></div><h3>Daily macro targets</h3><div class="profile-macros"><div><span>Protein</span><strong>${amount(plan.proteinGoal)}g</strong></div><div><span>Carbs</span><strong>${amount(plan.carbsGoal)}g</strong></div><div><span>Fat</span><strong>${amount(plan.fatGoal)}g</strong></div></div>
${plan.warnings.map(w=>`<p class="profile-warning">${esc(w)}</p>`).join('')}
<p class="note">Estimates for adults, not measurements. Based on the Mifflin–St Jeor equation, activity multiplier and an approximate calorie adjustment. Results vary; revisit as your weight and activity change.</p></div>`;}
function updateProfilePreview(){const form=$('#profile-form');const result=$('#profile-preview');if(!form||!result)return;
 const data=readProfileInput(form);
 const pace=$('#pace-field');if(pace)pace.hidden=data.goal==='maintain';
 try{const plan=estimatePlan(data);result.innerHTML=profilePreviewMarkup(plan);const save=$('#save-profile');if(save)save.disabled=false;}
 catch(err){result.innerHTML=`<div class="profile-empty"><span>◎</span><h3>Your recommended targets appear here</h3><p>${esc(err.message)}</p></div>`;const save=$('#save-profile');if(save)save.disabled=true;}
}
function profileTools(){return `<section class="profile-hub" aria-label="Profile shortcuts"><button class="profile-hub-tile" data-action="nav" data-view="foods"><span class="tile-icon">${uiIcon('foods')}</span><b>My foods & recipes</b><small>Saved foods, custom foods, recipes</small><span class="hub-chevron">›</span></button><button class="profile-hub-tile" data-action="nav" data-view="plan"><span class="tile-icon">${uiIcon('plan')}</span><b>Meal planner</b><small>Plan future days, copy previous meals</small><span class="hub-chevron">›</span></button><button class="profile-hub-tile" data-action="nav" data-view="settings"><span class="tile-icon">⚙</span><b>Settings & backups</b><small>Manual macros, theme, data export</small><span class="hub-chevron">›</span></button></section>`;}
function profilePage(){const v={...EMPTY_PROFILE,...S.profile};const goalChoices=[['lose','↘','Lose weight','A gradual calorie deficit'],['maintain','◎','Maintain weight','Fuel your current routine'],['gain','↗','Gain weight','A gradual calorie surplus']];
return `${pageHeader(S.profileSetup?'Your profile':'Let’s build your plan','PERSONAL NUTRITION PLAN',S.profileSetup?'Adjust your details or goal any time. Your food history stays intact.':'A few details will help personalize your calories and macros.')}
${profileTools()}<div class="profile-grid"><section class="card profile-form-card">
<div class="profile-step"><span class="step-dot">1</span><div><h2>What’s your goal?</h2><p>Choose what you want your daily nutrition budget to support.</p></div></div>
<form id="profile-form">
<div class="goal-choices">${goalChoices.map(([key,icon,title,sub])=>`<label class="goal-choice"><input type="radio" name="goal" value="${key}" ${v.goal===key?'checked':''}><span class="goal-icon">${icon}</span><span><b>${title}</b><small>${sub}</small></span><span class="goal-tick">✓</span></label>`).join('')}</div>
<div class="profile-step"><span class="step-dot">2</span><div><h2>About you</h2><p>Only used for your estimate. Stored on this device.</p></div></div>
<div class="fields-2"><div class="field"><label for="profile-age">Age (years)</label><input id="profile-age" name="age" type="number" min="18" max="100" step="1" inputmode="numeric" placeholder="e.g. 30" value="${esc(v.age)}" required></div><div class="field"><label for="profile-sex">Energy equation</label><select id="profile-sex" name="sex" required>${profileOptions('sex',[['','Choose one'],['female','Female equation'],['male','Male equation']],v.sex)}</select></div></div>
<div class="fields-3"><div class="field"><label for="profile-ft">Height (feet)</label><input id="profile-ft" name="heightFt" type="number" min="3" max="7" inputmode="numeric" placeholder="5" value="${esc(v.heightFt)}" required></div><div class="field"><label for="profile-in">Inches</label><input id="profile-in" name="heightIn" type="number" min="0" max="11" inputmode="numeric" placeholder="10" value="${esc(v.heightIn)}" required></div><div class="field"><label for="profile-lb">Current weight (lb)</label><input id="profile-lb" name="weightLb" type="number" min="77" max="770" step="0.1" inputmode="decimal" placeholder="180" value="${esc(v.weightLb)}" required></div></div>
<div class="field"><label for="profile-goal-weight">Target weight (lb) <span class="small">optional</span></label><input id="profile-goal-weight" name="goalWeightLb" type="number" min="77" max="770" step="0.1" inputmode="decimal" placeholder="Optional" value="${esc(v.goalWeightLb)}"></div>
<p class="note">The equation uses an adult female or male metabolic estimate. If neither fits your needs, you can skip this calculator and enter targets manually in Settings.</p>
<div class="profile-step"><span class="step-dot">3</span><div><h2>Activity and preferences</h2><p>These help set a starting estimate, not a guarantee.</p></div></div>
<div class="field"><label for="profile-activity">Typical activity level</label><select name="activity" id="profile-activity">${profileOptions('activity',Object.entries(ACTIVITY).map(([key,x])=>[key,x.label]),v.activity)}</select></div>
<div class="field" id="pace-field"><label for="profile-pace">Goal pace</label><select name="pace" id="profile-pace">${profileOptions('pace',[['0.5','Gentle · 0.5 lb/week'],['1','Moderate · 1 lb/week'],['1.5','Faster · 1.5 lb/week']],v.pace)}</select><p class="note">Approximate. Calorie adjustments are capped for gradual changes.</p></div>
<div class="field"><label for="profile-macros">Macro style</label><select name="macros" id="profile-macros">${profileOptions('macros',[['balanced','Balanced'],['highProtein','Higher protein'],['lowerCarb','Lower carbohydrate']],v.macros)}</select></div>
<div class="profile-submit"><button class="btn full" id="save-profile" type="submit">${S.profileSetup?'Recalculate & save targets':'Create my plan →'}</button>
${!S.profileSetup?`<button class="btn secondary full" type="button" data-action="skip-profile">I’ll set this up later</button>`:''}
<p class="note">Saving updates Dashboard, Log, Goals, and the targets in Settings. Your previous meal logs are never reset. Exercise calories are not added again because activity is included in the estimate.</p></div>
</form></section>
<aside class="card profile-result-card"><div class="card-hd"><h2>Your personal targets</h2><span class="label-tag">PREVIEW</span></div><div id="profile-preview" aria-live="polite"></div><div class="profile-settings-link">Prefer custom targets? <a href="#settings" data-action="nav" data-view="settings">Edit manually in Settings →</a></div></aside></div>`;}

function settingsPage(){const v=S.settings;return `${pageHeader('Settings','YOUR APP, YOUR RULES','All settings are stored locally on this device.')}<div class="two-col"><div class="left-stack"><section class="card"><div class="card-hd"><h2>Daily targets</h2><button class="profile-link" data-action="nav" data-view="profile">Recalculate in Profile →</button></div><form id="goals-form"><div class="fields-2">${[['Daily calories','calorieGoal','kcal'],['Protein','proteinGoal','g'],['Carbohydrates','carbsGoal','g'],['Fat','fatGoal','g'],['Water','waterGoal','mL'],['Fasting target','fastHours','hours']].map(([name,key,unit])=>`<div class="field"><label for="goal-${key}">${name} (${unit})</label><input type="number" id="goal-${key}" name="${key}" min="1" max="100000" step="1" value="${round(v[key])}" required></div>`).join('')}</div><button class="btn" type="submit">Save targets</button></form></section><section class="card"><div class="card-hd"><h2>Preferences</h2></div><div class="settings-row"><div><b>Count exercise toward calorie allowance</b><small>Off by default to avoid double counting energy expenditure.</small></div><input class="toggle" type="checkbox" id="exercise-budget" ${v.exerciseBudget?'checked':''}></div><div class="settings-row"><div><b>Light theme</b><small>Dark theme is the default.</small></div><input class="toggle" type="checkbox" id="theme-toggle" ${v.theme==='light'?'checked':''}></div></section></div>
<div class="right-stack"><section class="card"><div class="card-hd"><h2>Backups</h2></div><p class="note">Save a backup in Files or iCloud Drive. iOS can clear browser data, so a backup matters.</p><div class="stack">${btn('export-json','↓ Export full backup','')}${btn('export-csv','↓ Export food diary CSV')}<button class="btn secondary smallbtn" data-action="import-open">↑ Restore from backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></div></section><section class="card"><div class="card-hd"><h2>Apple AI & fitness</h2></div><p class="note">Use an Apple Intelligence Shortcut to estimate a meal from a camera photo, then paste the resulting nutrition JSON into the app. No third party AI key is needed.</p><div class="stack">${btn('open-photo','Set up photo logging','')}${btn('open-ai-import','Paste Shortcut response')}</div><p class="note">WHOOP or Apple Health workout syncing requires an approved API, Shortcut import, or companion app. The static site alone cannot read HealthKit.</p></section><section class="card"><div class="card-hd"><h2>Storage status</h2></div><p class="note">Database: IndexedDB on this iPhone only. GitHub hosts code but does not store your personal food entries.</p>${btn('storage-check','Check device storage','secondary')}<div class="divider"></div><button class="btn danger smallbtn" data-action="clear-data">Erase all local data</button></section></div></div>`;}
function modalShell(title,content){return `<div class="modal-backdrop" data-action="close-backdrop"><div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-head"><h2>${title}</h2><button class="sheet-close" data-action="close-modal" aria-label="Close">×</button></div>${content}</div></div>`;}
const tabs=(which)=>`<div class="sheet-tabs">${[['search','Search'],['recent','Recent'],['myfoods','Saved'],['barcode','Barcode'],['photo','Photo']].map(([id,label])=>`<button data-action="modal-tab" data-tab="${id}" class="${which===id?'selected':''}">${label}</button>`).join('')}</div><details class="more-food-tools"><summary>More logging options</summary><div class="extra-food-tabs">${[['describe','Voice / text AI'],['facts','Paste nutrition'],['recipes','Recipes'],['manual','Custom food'],['import','Import AI result']].map(([id,label])=>`<button data-action="modal-tab" data-tab="${id}" class="${which===id?'selected':''}">${label}</button>`).join('')}</div></details>`;

function renderModal(){const root=$('#modal-root');if(!S.modal){root.innerHTML='';return;}
 if(S.modal==='quick')root.innerHTML=modalShell('Quick log',`<p class="note">What would you like to log for ${prettyDate(S.date,{month:'short',day:'numeric'})}?</p><div class="quick-sheet-grid"><button data-action="open-add"><span>🍽️</span><b>Food</b></button><button data-action="open-photo"><span>📷</span><b>Photo AI</b></button><button data-action="open-barcode"><span>▥</span><b>Barcode</b></button><button data-action="open-describe"><span>🎙️</span><b>Describe / voice</b></button><button data-action="quick-water"><span>💧</span><b>Water +250 mL</b></button><button data-action="open-workout"><span>⚡</span><b>Exercise</b></button><button data-action="open-weight"><span>⚖️</span><b>Weight</b></button><button data-action="open-recipe"><span>🧑‍🍳</span><b>New recipe</b></button></div>`);

 if(S.modal==='add')root.innerHTML=modalShell('Add food',tabs(S.tab)+addModal());
 if(S.modal==='recipe')root.innerHTML=modalShell('Create recipe',recipeModal());
 if(S.modal==='workout')root.innerHTML=modalShell('Log workout',`<form id="workout-form"><div class="field"><label>Workout / activity</label><input name="name" placeholder="Judo, cycling, strength training…" required maxlength="100"></div><div class="fields-2"><div class="field"><label>Duration (minutes)</label><input type="number" name="minutes" min="0" max="1440" value="60" required></div><div class="field"><label>Active energy (kcal)</label><input type="number" name="calories" min="0" max="10000" value="300" required></div></div><p class="note">Use actual workout energy when available. This is not an automatically verified WHOOP value.</p><button class="btn full" type="submit">Save workout for ${prettyDate(S.date,{month:'short',day:'numeric'})}</button></form>`);
 if(S.modal==='weight')root.innerHTML=modalShell('Record weight',`<form id="weight-form"><div class="field"><label>Weight (lb)</label><input type="number" name="weight" min="50" max="1400" step="0.1" placeholder="e.g. 170.5" required autofocus></div><p class="note">Recorded for ${prettyDate(S.date)}.</p><button class="btn full" type="submit">Save weight</button></form>`);
 if(S.modal==='plan')root.innerHTML=modalShell('Copy a day into your plan',`<form id="plan-form"><p class="note">Target date: <strong>${prettyDate(S.planTarget)}</strong>. Choose a day that already has food logged, then copy it as a future plan.</p><div class="field"><label>Copy meals from</label><input type="date" name="source" value="${S.date}" required></div><p class="note">This creates a plan only. It does not add calories until you log the plan.</p><button class="btn full" type="submit">Save day plan</button></form>`);
 if(S.modal==='portion')root.innerHTML=modalShell('Add to food diary',portionModal());
}
function savedMatchesHtml(){
 const q=S.query.toLowerCase().trim();if(!q)return '<p class="note">Your recent meals and saved foods appear here when you start typing.</p>';
 const used=new Set(),recent=[...records('logs')].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''))
 .filter(r=>r.name?.toLowerCase().includes(q) || q.split(/\s+(?:from|at)\s+/)[0].length>5 && r.name?.toLowerCase().includes(q.split(/\s+(?:from|at)\s+/)[0]))
 .filter(r=>{const key=r.name+'|'+r.calories;if(used.has(key))return false;used.add(key);return true;}).slice(0,4);
 const favorites=records('foods').filter(r=>r.name?.toLowerCase().includes(q)).slice(0,3);
 if(!recent.length&&!favorites.length)return '';
 return `<section class="quick-matches"><strong>Previously logged / saved</strong>${recent.map(r=>`<div class="food-result"><div class="result-title"><b>${esc(r.name)}</b><small>Previously logged · ${amount(r.protein)}g protein</small></div><div class="result-right"><strong>${amount(r.calories)} kcal</strong><button class="round-add" data-action="repeat-log" data-id="${esc(r.id)}">+</button></div></div>`).join('')}${foodResults(favorites,'select-food')}</section>`;
}
function liveMatchHtml(){
 if(!S.query.trim())return '';
 if(S.smartFood)return smartFoodCard(S.smartFood);
 const q=interpretFoodQuery(S.query);
 if(q.restaurant)return '<p class="note" role="status">Restaurant name recognized. Exact menu nutrition is not in our public database. If this dish is not listed below, use Photo or Voice / text AI under More logging options.</p>';
 return '';
}
function updateLiveResults(){if(S.modal==='add'&&S.tab==='search'){
 const out=$('#smart-match');if(out)out.innerHTML=liveMatchHtml();
 const saved=$('#saved-matches');if(saved)saved.innerHTML=savedMatchesHtml();
}}
// A separate, throttled product lookup for unfamiliar packaged foods.
// This is best-effort only; no secret API key is exposed to the browser.
async function autoFindProducts(query){
 const seq=++S.productSearchSeq;
 const hint=$('#product-status');if(hint)hint.textContent='Searching public food databases…';
 const dish=interpretFoodQuery(query).dish;
 if(dish.length<2)return;
 const results=await Promise.allSettled([findProducts(dish),findUSDA(dish)]);
 if(seq!==S.productSearchSeq||S.modal!=='add'||S.tab!=='search'||S.query.trim()!==query)return;
 const found=results.filter(x=>x.status==='fulfilled').flatMap(x=>x.value);
 // Retain only relevant candidates; a search term shared with an ingredient isn't sufficient.
 S.online=rankFoodMatches(query,found,30);
 const view=$('#modal-food-results');if(view)view.innerHTML=foodResults(matchedFoods(),'select-food');
 if(hint)hint.textContent=S.online.length?`Found ${S.online.length} relevant online food entries. Check the brand and serving size.`:
   (results.every(x=>x.status==='rejected')?'Online food databases are temporarily unavailable.':'No exact match in public food databases. Try a saved food or estimate.');
}
function smartFoodCard(v){
 if(!v)return '';
 return `<section class="smart-result" aria-label="Estimated food"><div class="smart-result-head"><span class="smart-tag">Estimated from ingredients</span><span class="tiny">${esc(v.range[0])}–${esc(v.range[1])} kcal possible</span></div><strong class="smart-result-title">${esc(v.name)}</strong><div class="smart-result-stats"><div><strong>${amount(v.calories)}</strong><small>calories</small></div><div><strong>${amount(v.protein)} g</strong><small>protein</small></div><div><strong>${amount(v.carbs)} g</strong><small>carbs</small></div><div><strong>${amount(v.fat)} g</strong><small>fat</small></div></div><p class="note">${esc(v.menuUrl?'Menu ingredients verified, nutrition estimated.':'Generic recipe estimate, not the restaurant’s published nutrition.')}</p><details class="smart-details"><summary>What is this estimate based on?</summary><div class="smart-ingredients">${v.ingredients.map(r=>`<div><span>${esc(r.name)}</span><b>${amount(r.calories)} kcal</b></div>`).join('')}</div><p class="note">${esc(v.notes)}</p>${v.menuUrl?`<p><a href="${esc(v.menuUrl)}" target="_blank" rel="noopener noreferrer">See restaurant menu ↗</a></p>`:''}</details><button class="btn full" data-action="review-smart">Review &amp; log this meal</button></section>`;
}
function smartUnknownCard(){return `<div class="smart-unknown">No reliable recipe estimate for that description yet. Try a simpler dish name, check the online food results, or use the Describe tab with Apple Intelligence. I won't invent nutrition for an unrecognized meal.</div>`;}
function addModal(){switch(S.tab){
case 'myfoods':return `<p class="note">Your saved foods. Select one to change its portion and log it.</p>${foodResults(records('foods'),'select-food')}`;
case 'recent':{const latest=[...records('logs')].sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''));const seen=new Set();const unique=latest.filter(r=>{const key=r.name+'|'+r.grams+'|'+r.calories;if(seen.has(key))return false;seen.add(key);return true;}).slice(0,25);return `<p class="note">Quickly repeat meals you have logged before into ${S.meal}.</p>${unique.length?unique.map(r=>`<div class="food-result"><div class="result-title"><b>${esc(r.name)}</b><small>${esc(r.meal)} · ${amount(r.protein)}g protein · ${amount(r.carbs)}g carbs</small></div><div class="result-right"><strong>${amount(r.calories)} kcal</strong><button class="round-add" data-action="repeat-log" data-id="${esc(r.id)}" aria-label="Repeat ${esc(r.name)}">+</button></div></div>`).join(''):'<div class="no-items">Your previously logged meals will show here.</div>'}`;}
case 'recipes':return `<div class="card-hd"><h2>Your recipes</h2>${btn('open-recipe','＋ Recipe','secondary')}</div>${records('recipes').length?records('recipes').map(r=>`<div class="recipe-row"><div><strong>${esc(r.name)}</strong><small>${amount(r.calories)} kcal/serving</small></div>${btn('log-recipe','Log serving','secondary',`data-id="${esc(r.id)}"`)}</div>`).join(''):'<div class="no-items">No recipes yet. Create one to log a full meal in one tap.</div>'}`;

case 'search':return `<div class="field"><label for="food-search">Search foods, brands, or restaurant meals</label><input class="searchbox" id="food-search" autocomplete="off" autofocus placeholder="Coke, egg, butter chicken from Spice 6" value="${esc(S.query)}" enterkeyhint="search"></div><p class="search-hint">Results appear automatically. Nutrition is shown per can, item, cup, or normal serving where available.</p><div id="saved-matches">${savedMatchesHtml()}</div><div id="smart-match">${liveMatchHtml()}</div><div class="lookup-header"><h3>Best matches</h3></div><div id="modal-food-results">${S.query.trim()?foodResults(matchedFoods(),'select-food'):'<div class="search-empty">Try <button data-action="fill-search" data-query="Coke">Coke</button>, <button data-action="fill-search" data-query="eggs">eggs</button>, or <button data-action="fill-search" data-query="butter chicken from Spice 6">a restaurant meal</button>.</div>'}</div><p class="note" id="product-status" role="status"></p><details class="other-databases"><summary>Not seeing the right food?</summary><p class="note">Our public nutrition databases do not include every restaurant menu. You can review ingredient-based estimates, create a custom food, or use photo and voice tools.</p>${btn('search-online','Retry online search','secondary')} ${btn('open-manual','Add custom food','secondary')}</details>`;
case 'describe':return `<div class="banner"><b>Describe food in your own words</b>Type or use the microphone on your iPhone keyboard. Apple Intelligence processes the description through your separately configured Shortcut, then you confirm the estimate before saving.</div><div class="field" style="margin-top:12px"><label>What did you eat?</label><textarea id="describe-text" rows="5" placeholder="Example: Cava bowl with chicken, rice, hummus, pita chips and garlic sauce">${esc(S.description)}</textarea></div><div class="modal-actions">${btn('analyze-description','Ask Siri / Apple AI','')}${btn('copy-description','Copy description','secondary')}</div><div class="stack" style="margin-top:12px">${btn('describe-to-search','Look up a menu item','secondary')}${btn('open-ai-import','Paste AI estimate to review','secondary')}</div><p class="note">Siri can run a Shortcut named “PlatePilot Food AI.” The shortcut must accept provided text input, or ask for it itself. See SHORTCUTS.md. Estimates are not official restaurant nutrition facts.</p>`;
case 'facts':return `<div class="banner"><b>Import official nutrition facts</b>Open a restaurant's published nutrition page, copy the nutritional numbers, and paste them below. PlatePilot will extract calories and macros without guessing.</div><div class="field" style="margin-top:12px"><label>Food or menu item name</label><input id="facts-name" maxlength="130" value="${esc(S.factsName)}" placeholder="e.g. Sweetgreen harvest bowl"></div><div class="field"><label>Published nutrition text (for ONE serving)</label><textarea id="facts-text" rows="6" placeholder="Calories 640, Total Fat 25g, Total Carbohydrate 70g, Protein 35g">${esc(S.factsText)}</textarea></div><div class="modal-actions">${btn('parse-facts','Extract and review facts','')}${btn('facts-to-web','Find restaurant nutrition online','secondary')}</div><p class="note">Select the correct serving. If a value is missing it appears as zero for you to correct before saving. This does not read websites automatically.</p>`;
case 'manual':return `<form id="manual-form"><div class="field"><label>Food name</label><input name="name" placeholder="e.g. Homemade chili" maxlength="130" required></div><div class="field"><label>Nutrition values are per 100 grams</label><p class="note" style="margin:0">Use the package label or measured recipe values. If the label is per serving, convert to 100 g first.</p></div><div class="fields-2">${[['Calories','calories','kcal'],['Protein','protein','g'],['Carbs','carbs','g'],['Fat','fat','g'],['Fiber','fiber','g']].map(([label,key,unit])=>`<div class="field"><label>${label} (${unit})</label><input type="number" name="${key}" min="0" max="10000" step="0.1" value="0" required></div>`).join('')}</div><div class="field"><label>Portion to log (g)</label><input type="number" name="grams" min="1" max="10000" step="1" value="100" required></div><div class="field"><label>Meal</label>${mealSelect()}</div><label style="display:flex;gap:10px;align-items:center;font-size:12px;margin-bottom:13px"><input type="checkbox" name="save" checked> Save in my food library</label><button class="btn full" type="submit">Save food to diary</button></form>`;
case 'photo':return `<p class="note">Choose a photo for your journal, then run your Apple Intelligence Shortcut to estimate nutrition. Because browsers cannot directly call Siri, paste the model's JSON response to review it before saving.</p><label class="drop-photo" for="food-photo-input">${S.photo?`<img src="${S.photo}" alt="Selected meal photo" />`:`<div style="font-size:38px">📷</div><b>Choose or take food photo</b><span>Photo stays on your device when saved</span>`}</label><input id="food-photo-input" type="file" accept="image/*" capture="environment" hidden><div class="field" style="margin-top:13px"><label>Meal description (optional but improves estimate)</label><textarea id="photo-description" placeholder="Chicken thighs, a cup of rice, olive oil and broccoli">${esc(S.photoDesc||'')}</textarea></div><div class="modal-actions">${btn('copy-ai-prompt','Copy AI prompt','secondary')}${btn('run-shortcut','Run Apple AI Shortcut','')}</div><div class="divider"></div><div class="stack">${btn('modal-import','Paste AI result and review','secondary')}</div><p class="note">A separately created iPhone Shortcut takes its own photo. Your photo selected here does not transfer into Shortcuts automatically. Instructions: SHORTCUTS.md.</p>`;
case 'barcode':return `<div class="field"><label>Type the numbers under a barcode</label><input id="barcode-input" inputmode="numeric" autocomplete="off" placeholder="e.g. 737628064502"></div><div class="modal-actions">${btn('lookup-barcode','Look up barcode','')}${btn('start-barcode','Scan with camera','secondary')}</div><div id="barcode-camera" style="margin-top:13px"></div><p class="note">Camera scanning only works on browsers that support the BarcodeDetector API. Manual entry works on more devices. Product nutrition comes from Open Food Facts and may need verification.</p>`;
case 'import':return `<div class="banner"><b>Apple Intelligence import</b>Run the Shortcut described in SHORTCUTS.md. It copies estimated nutrition as JSON. Return here and paste the result.</div><div class="field" style="margin-top:14px"><label>Paste food estimate or workout JSON</label><textarea id="ai-json" class="ai-output" placeholder='{"name":"Chicken bowl","calories":700,"protein":40,"carbs":65,"fat":28}'></textarea></div><div class="modal-actions">${btn('paste-clipboard','Paste clipboard','secondary')}${btn('parse-ai','Review estimate','')}</div><p class="note">Photo and AI predictions can misjudge serving sizes and oils. Review and edit every result. No prediction is medically precise.</p>`;
case 'ai-review':return `<form id="ai-save-form"><div class="banner"><b>Review estimated nutrition</b>Calories and macros are editable. Use a cautious serving estimate rather than treating the photo as a measurement.</div><div style="height:14px"></div><div class="field"><label>Food name</label><input name="name" maxlength="130" required value="${esc(S.aiFood?.name)}"></div><div class="fields-2">${[['Calories','calories'],['Protein (g)','protein'],['Carbs (g)','carbs'],['Fat (g)','fat'],['Fiber (g)','fiber']].map(([label,key])=>`<div class="field"><label>${label}</label><input type="number" min="0" max="10000" name="${key}" step="0.1" required value="${round(S.aiFood?.[key])}"></div>`).join('')}</div><div class="field"><label>Meal</label>${mealSelect()}</div>${S.aiFood?.notes?`<p class="note">AI notes: ${esc(S.aiFood.notes)}</p>`:''}<button type="submit" class="btn full">Confirm and log food</button></form>`;
default:return '';
}}
function mealSelect(){return `<select name="meal">${MEALS.map(m=>`<option ${m===S.meal?'selected':''}>${m}</option>`).join('')}</select>`;}
function matchedFoods(){
 const base=[...POPULAR_FOODS,...records('foods'),...S.online,...SEED];
 return rankFoodMatches(S.query,base,30);
}
function portionModal(){const f=S.food;if(!f)return '';const t=scale(f,S.grams);const g=f.servingG||100;const normal=!!f.servingLabel;
 return `<div class="banner"><b>${esc(f.name)}</b>${esc(f.brand||f.source||'Food database')} · ${normal?esc(f.servingLabel):'100 g'}: ${amount(scale(f,g).calories)} kcal${f.verifiedServing?' · manufacturer nutrition facts':''}</div>${normal?`<div class="field" style="margin-top:17px"><label>How many ${esc(f.servingLabel)}?</label><input id="portion-servings" type="number" min="0.1" max="50" step="0.5" value="${Number((S.grams/g).toFixed(2))}"></div><details class="portion-advanced"><summary>Edit amount in grams instead</summary>`:''}<div class="field" style="margin-top:${normal?10:17}px"><label>Quantity (grams${normal?' or approximate ml equivalent':''})</label><input id="portion-grams" type="number" min="1" max="10000" step="1" value="${amount(S.grams)}"></div>${normal?'</details>':''}<div class="field"><label>Meal</label><select id="portion-meal">${MEALS.map(m=>`<option ${S.meal===m?'selected':''}>${m}</option>`).join('')}</select></div><div id="portion-preview" class="preview-totals">${portionPreview(t)}</div><p class="note">${f.verifiedServing?'Calories and macros use the manufacturer’s label for the selected serving. Converting drink volume to grams is approximate.':'Values are calculated from the available nutrition data; check the serving size.'}</p><div class="modal-actions">${btn('save-favorite','☆ Save food','secondary')}${btn('save-portion','＋ Log this portion','')}</div>`;
}
function portionPreview(t){return [['Calories',t.calories,'kcal'],['Protein',t.protein,'g'],['Carbs',t.carbs,'g'],['Fat',t.fat,'g']].map(([l,n,u])=>`<div>${l}<b>${amount(n,1)} ${u}</b></div>`).join('');}
function recipeModal(){const t=totals(S.recipeIngredients.map(i=>scale(i,i.grams)));const count=safeGoal(S.recipeServings);const matches=[...records('foods'),...SEED].filter(x=>!S.recipeQuery || x.name.toLowerCase().includes(S.recipeQuery.toLowerCase())).slice(0,6);return `<form id="recipe-form"><div class="fields-2"><div class="field"><label>Recipe name</label><input name="name" value="${esc(S.recipeName)}" placeholder="e.g. Chicken rice bowls" required maxlength="130"></div><div class="field"><label>Servings</label><input type="number" name="servings" min="1" max="100" step="1" value="${S.recipeServings}" required></div></div></form><div class="field"><label>Add ingredients from food library</label><input id="ingredient-query" class="searchbox" placeholder="Search ingredients" autocomplete="off" value="${esc(S.recipeQuery)}"></div><div id="ingredient-matches">${matches.map(f=>`<div class="food-result"><div class="result-title"><b>${esc(f.name)}</b><small>${amount(f.calories)} kcal per 100 g</small></div><button class="round-add" data-action="recipe-add" data-id="${esc(f.id)}">+</button></div>`).join('')}</div><div class="divider"></div><div class="card-hd"><h2>Ingredients (${S.recipeIngredients.length})</h2></div>${S.recipeIngredients.length?S.recipeIngredients.map((r,i)=>`<div class="recipe-row"><div><strong>${esc(r.name)}</strong><small>${amount(scale(r,r.grams).calories)} kcal</small></div><div style="display:flex;gap:5px;align-items:center"><input type="number" data-recipe-index="${i}" class="recipe-grams" min="1" step="1" value="${r.grams}" style="width:70px;background:var(--panel2);border:1px solid var(--line);padding:8px;color:var(--txt);border-radius:9px"><span class="tiny">g</span><button class="trash" data-action="recipe-remove" data-index="${i}">×</button></div></div>`).join(''):`<div class="no-items">Search for an ingredient and tap + to add it.</div>`}<div class="preview-totals">${portionPreview({calories:t.calories/count,protein:t.protein/count,carbs:t.carbs/count,fat:t.fat/count})}</div><p class="note">Values above are per serving, based on ${count} serving${count===1?'':'s'}.</p><button class="btn full" data-action="save-recipe">Save recipe</button>`;}
function openModal(modal='add',tab='search',meal=null){if(meal)S.meal=meal;else if(!MEALS.includes(S.meal))S.meal='Lunch';S.modal=modal;S.tab=tab;S.online=[];S.query='';S.filters='all';S.searchStatus='';S.smartFood=null;S.smartSearchTried=false;S.productSearchSeq++;clearTimeout(S.productTimer);if(modal==='recipe'){S.recipeIngredients=[];S.recipeName='';S.recipeServings=2;S.recipeQuery='';}if(modal==='add' && tab==='photo'){S.photo=null;S.photoDesc='';}renderModal();}
function closeModal(){stopScan();clearTimeout(S.productTimer);S.productSearchSeq++;S.modal=null;renderModal();}
function chooseFood(id){const f=[...records('foods'),...POPULAR_FOODS,...SEED,...S.online,...records('recipes')].find(f=>f.id===id);if(!f){toast('Food not available. Search again.');return;}S.food=f;S.grams=(f.servingG||100)*(interpretFoodQuery(S.query).quantity||1);S.modal='portion';renderModal();}
function mkLog(food,grams,meal,sourceOverride){return {id:newId(),date:S.date,meal,name:food.name,grams, ...scale(food,grams),source:sourceOverride||food.source||'Manual',createdAt:new Date().toISOString()};}
function addLogFromAI(r,meal){return {id:newId(),date:S.date,meal,name:r.name,grams:null,calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,fiber:r.fiber||0,photo:S.photo||null,source:S.aiFood?.source||(S.aiFood?.notes?.startsWith('From pasted published nutrition facts')?'Published nutrition · reviewed':'Apple AI estimate · edited'),notes:r.notes||'',createdAt:new Date().toISOString()};}
function getFood(id){return [...records('foods'),...SEED,...S.online].find(x=>x.id===id);}
async function changeWater(delta){const item={id:S.date,date:S.date,ml:Math.max(0,getWater()+delta)};await put('water',item);await refresh();}
async function downloadBackup(){const data=await dataDump();download(`platepilot-backup-${dateKey()}.json`,JSON.stringify(data,null,2),'application/json');toast('Backup exported. Save it in Files or iCloud Drive.');}
async function exportCSV(){const hdr=['date','meal','food','grams','calories','protein_g','carbs_g','fat_g','fiber_g','source'];const rows=records('logs').map(r=>[r.date,r.meal,r.name,r.grams??'',r.calories,r.protein,r.carbs,r.fat,r.fiber,r.source].map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(','));download(`platepilot-diary-${dateKey()}.csv`,[hdr.join(','),...rows].join('\r\n'),'text/csv;charset=utf-8');toast('Diary CSV exported.');}
function aiPrompt(){const desc=($('#photo-description')?.value||S.photoDesc||'').trim();return `You are estimating food nutrition from a food PHOTO AND DESCRIPTION. Inspect the image if a photo is attached. Description: ${desc||'(no description provided)'}. Identify ingredients, conservative plausible portions, oils, sauces, and hidden extras. Use a cautious upper-middle calorie estimate (avoid undercounting), but do not artificially inflate protein. If no photo is provided, base estimates only on the description. Output ONLY valid JSON, no Markdown or explanation: {"name":"meal name","calories":720,"protein":42,"carbs":65,"fat":30,"fiber":5,"notes":"assumptions and uncertainty"}. Numbers are for the whole meal. If insufficient information, make assumptions explicit in notes. Never claim the estimate is precise.`;}
async function imageToJpeg(file){if(file.size>25*1024*1024)throw Error('Image too large (25 MB maximum).');return new Promise((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{try{const m=750;const k=Math.min(1,m/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);const result=c.toDataURL('image/jpeg',.68);URL.revokeObjectURL(url);resolve(result);}catch(e){URL.revokeObjectURL(url);reject(e);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Unable to read image.'));};img.src=url;});}
function stopScan(){if(scanRAF)cancelAnimationFrame(scanRAF);scanRAF=null;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}}
async function scanBarcode(){if(!('BarcodeDetector' in window)){toast('Camera barcode detection unavailable. Enter digits manually.');return;}const div=$('#barcode-camera');if(!div)return;try{const detector=new BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});div.innerHTML='<video id="scanner-video" playsinline muted autoplay style="width:100%;max-height:280px;border-radius:14px"></video><p class="note">Point camera at barcode…</p>';const video=$('#scanner-video');video.srcObject=stream;await video.play();let last=0;const scan=async timestamp=>{if(!stream)return;if(timestamp-last>550){last=timestamp;try{const found=await detector.detect(video);if(found.length){stopScan();$('#barcode-input').value=found[0].rawValue;toast('Barcode scanned. Looking up product…');await barcodeLookup(found[0].rawValue);return;}}catch{}}scanRAF=requestAnimationFrame(scan);};scanRAF=requestAnimationFrame(scan);}catch(e){stopScan();toast('Camera unavailable: '+e.message);}}
async function barcodeLookup(v){try{S.busy=true;const f=await findBarcode(v);S.online=[f];S.food=f;S.grams=100;S.modal='portion';stopScan();renderModal();}catch(e){toast(e.message);}finally{S.busy=false;}}
function normalizeWorkoutDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:S.date;}
async function acceptAIText(txt){const v=parseAI(txt);if(v.type==='workout'){await put('workouts',{id:newId(),date:normalizeWorkoutDate(v.date),name:v.name,minutes:v.minutes,calories:v.calories,source:'Shortcut import'});closeModal();await refresh();toast('Workout imported.');return;}S.aiFood=v;S.tab='ai-review';renderModal();}
async function handleAction(e){const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='close-backdrop' && e.target!==el)return;if(action==='nav' && el.tagName==='A')e.preventDefault();
 try{switch(action){
case 'nav':S.view=el.dataset.view;closeModal();render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'open-quick':openModal('quick');break;
 case 'quick-water':closeModal();await changeWater(250);toast('Added 250 mL water.');break;
 case 'repeat-log':{const entry=records('logs').find(x=>x.id===el.dataset.id);if(!entry){toast('Previous entry not found.');break;}await put('logs',{...entry,id:newId(),date:S.date,meal:S.meal,source:'Repeated entry',createdAt:new Date().toISOString()});closeModal();await refresh();toast('Meal added to '+S.meal+'.');break;}
case 'shift-date':S.date=shiftDate(S.date,Number(el.dataset.days));render();break;
 case 'skip-profile':await put('meta',{id:'profileIntroDismissed',value:true});S.view='dashboard';render();break;
case 'close-backdrop':case 'close-modal':closeModal();break;
case 'open-add':openModal('add','search',el.dataset.meal);break;
case 'open-manual':openModal('add','manual');break;
case 'open-photo':openModal('add','photo');break;
case 'open-barcode':openModal('add','barcode');break;
case 'open-ai-import':openModal('add','import');break;
case 'modal-import':S.photoDesc=$('#photo-description')?.value||S.photoDesc;S.tab='import';renderModal();break;
case 'modal-tab':stopScan();S.tab=el.dataset.tab;renderModal();break;
case 'filter':S.filters=el.dataset.filter;renderModal();break;
case 'analyze-search-siri':{
 const q=($('#food-search')?.value||S.query).trim();if(!q){toast('Type your food description first.');break;}
 S.description=q;window.location.href='shortcuts://run-shortcut?name=PlatePilot%20Voice%20Log&input=text&text='+encodeURIComponent(q);
 toast('Run your configured Shortcut, then return to Paste AI to import its nutrition result.');break;}
case 'review-smart':{
 if(!S.smartFood){toast('Type a recognized meal first.');break;}
 S.aiFood={...S.smartFood};S.tab='ai-review';renderModal();break;}
case 'smart-search':{const q=($('#food-search')?.value||S.query).trim();if(q.length<2){toast('Enter a food name first.');break;}void autoFindProducts(q);break;}
case 'search-online':{
 const q=($('#food-search')?.value||S.query).trim();if(q.length<2){toast('Enter at least two characters.');break;}
 S.query=q;void autoFindProducts(q);break;}
case 'fill-search':{const q=el.dataset.query||'';S.query=q;S.online=[];S.smartFood=estimateRestaurantMeal(q);renderModal();clearTimeout(S.productTimer);S.productTimer=setTimeout(()=>void autoFindProducts(q),450);break;}
case 'search-web':case 'facts-to-web':{
 const q=(el.dataset.action==='facts-to-web'?($('#facts-name')?.value||S.factsName):($('#food-search')?.value||S.query)).trim();
 if(q.length<2){toast('Enter a restaurant and menu item first.');break;}
 const url='https://www.google.com/search?q='+encodeURIComponent(q+' official nutrition calories protein carbs fat');
 window.open(url,'_blank','noopener');break;}
case 'open-describe':openModal('add','describe');break;
case 'analyze-description':{
 const description=($('#describe-text')?.value||S.description).trim();if(!description){toast('Enter what you ate first.');break;}
 S.description=description;
 const u='shortcuts://run-shortcut?name=PlatePilot%20Voice%20Log&input=text&text='+encodeURIComponent(description);
 window.location.href=u;toast('Run the Shortcut, then return and paste the estimate.');break;}
case 'copy-description':{
 S.description=($('#describe-text')?.value||S.description).trim();
 if(!S.description){toast('Enter food details first.');break;}
 try{await navigator.clipboard.writeText(S.description);toast('Description copied for your Shortcut.');}catch{toast('Select and copy the text manually.');}break;}
case 'describe-to-search':{
 S.description=($('#describe-text')?.value||S.description).trim();
 S.query=S.description.slice(0,110);S.tab='search';S.filters='all';renderModal();break;}
case 'parse-facts':{
 S.factsName=($('#facts-name')?.value||S.factsName).trim();S.factsText=($('#facts-text')?.value||S.factsText).trim();
 try{S.aiFood=parsePublishedFacts(S.factsText,S.factsName||'Restaurant food');S.tab='ai-review';renderModal();toast('Published nutrition extracted. Review all fields.');}catch(err){toast(err.message);}break;}

case 'select-food':chooseFood(el.dataset.id);break;
case 'favorite':case 'log-saved':chooseFood(el.dataset.id);break;
case 'save-favorite':{const f={...S.food,id:newId(),source:S.food.source||'Saved'};await put('foods',f);await refresh();toast('Saved in your food library.');break;}
case 'save-portion':{S.grams=$('#portion-servings')?Number($('#portion-servings').value)*(S.food.servingG||100):Number($('#portion-grams')?.value)||S.grams;S.meal=$('#portion-meal')?.value||S.meal;if(S.grams<1||S.grams>10000){toast('Enter a valid portion in grams.');break;}await put('logs',mkLog(S.food,S.grams,S.meal));closeModal();await refresh();toast('Food logged.');break;}
case 'lookup-barcode':await barcodeLookup($('#barcode-input')?.value||'');break;
case 'start-barcode':await scanBarcode();break;
case 'copy-ai-prompt':{S.photoDesc=$('#photo-description')?.value||'';const str=aiPrompt();await navigator.clipboard.writeText(str);toast('AI prompt copied. Add it to your Shortcut.');break;}
case 'run-voice':{window.location.href='shortcuts://run-shortcut?name=PlatePilot%20Voice%20Log';toast('If no Shortcut opens, configure it using SHORTCUTS.md.');break;}
case 'run-shortcut':{S.photoDesc=$('#photo-description')?.value||'';window.location.href='shortcuts://run-shortcut?name=PlatePilot%20Food%20AI';toast('If no Shortcut opens, set one up from SHORTCUTS.md.');break;}
case 'paste-clipboard':{try{$('#ai-json').value=await navigator.clipboard.readText();toast('Clipboard pasted.');}catch{toast('Tap the box and use Paste from the iPhone menu.');}break;}
case 'parse-ai':await acceptAIText($('#ai-json')?.value||'');break;
case 'open-workout':openModal('workout');break;
case 'delete-workout':if(confirm('Delete this workout?')){await remove('workouts',el.dataset.id);await refresh();}break;
case 'delete-log':if(confirm('Remove this food log?')){await remove('logs',el.dataset.id);await refresh();}break;
case 'delete-weight':if(confirm('Delete this weight entry?')){await remove('weights',el.dataset.id);await refresh();}break;
case 'delete-recipe':if(confirm('Delete this saved recipe?')){await remove('recipes',el.dataset.id);await refresh();}break;
case 'delete-food':if(confirm('Delete this saved food?')){await remove('foods',el.dataset.id);await refresh();}break;
case 'open-weight':openModal('weight');break;
case 'water':await changeWater(Number(el.dataset.delta));break;
case 'start-fast':S.fastAt=new Date().toISOString();await put('meta',{id:'fastAt',value:S.fastAt});render();toast('Fasting timer started.');break;
case 'stop-fast':S.fastAt=null;await put('meta',{id:'fastAt',value:null});render();toast('Fasting timer ended.');break;
case 'export-json':await downloadBackup();break;
case 'export-csv':await exportCSV();break;
case 'import-open':$('#import-file').click();break;
case 'storage-check':{if(navigator.storage?.estimate){const z=await navigator.storage.estimate();const used=((z.usage||0)/1024/1024).toFixed(1);toast(`Estimated site storage used: ${used} MB. Back up regularly.`);}else toast('Your browser does not expose storage estimates.');break;}
case 'clear-data':if(confirm('Erase ALL PlatePilot logs, recipes, backups on this device, settings and planned meals? This cannot be undone unless you have exported a backup.')){if(confirm('Last confirmation: permanently erase local data?')){for(const t of ['logs','foods','recipes','water','workouts','weights','plans','meta'])await clear(t);S.settings={...DEFAULTS};S.profile={...EMPTY_PROFILE};S.profileSetup=false;S.fastAt=null;S.date=today();await refresh();toast('Local data erased.');}}break;
case 'open-recipe':openModal('recipe');break;
case 'recipe-add':{S.recipeName=$('#recipe-form [name=name]')?.value||S.recipeName;S.recipeServings=Number($('#recipe-form [name=servings]')?.value)||2;const food=getFood(el.dataset.id);if(food)S.recipeIngredients.push({...food,grams:100});renderModal();break;}
case 'recipe-remove':{S.recipeIngredients.splice(Number(el.dataset.index),1);renderModal();break;}
case 'save-recipe':{const name=$('#recipe-form [name=name]')?.value.trim();const servings=Number($('#recipe-form [name=servings]')?.value);if(!name||!S.recipeIngredients.length||!Number.isFinite(servings)||servings<1||servings>100){toast('Add a name, servings, and at least one ingredient.');break;}const sum=totals(S.recipeIngredients.map(r=>scale(r,r.grams)));const recipe={id:newId(),name:name.slice(0,130),servings,ingredients:S.recipeIngredients.map(r=>({...r})),...Object.fromEntries(['calories','protein','carbs','fat','fiber'].map(k=>[k,round(sum[k]/servings)])),source:'Your recipe'};await put('recipes',recipe);closeModal();S.view='foods';await refresh();toast('Recipe saved.');break;}
case 'log-recipe':{const r=records('recipes').find(x=>x.id===el.dataset.id);if(r){if(S.modal)closeModal();await put('logs',{id:newId(),date:S.date,meal:S.meal,name:r.name,grams:null,calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,fiber:r.fiber,source:'Saved recipe',createdAt:new Date().toISOString()});await refresh();toast('Recipe serving logged for '+prettyDate(S.date,{month:'short',day:'numeric'}));}break;}
case 'plan-copy':S.planTarget=el.dataset.date;openModal('plan');break;
case 'delete-plan':if(confirm('Delete the planned meals for this date?')){await remove('plans',el.dataset.date);await refresh();}break;
case 'apply-plan':{const p=records('plans').find(x=>x.date===el.dataset.date);if(!p||p.applied){toast('Plan already logged or unavailable.');break;}for(const item of p.items){await put('logs',{...item,id:newId(),date:p.date,createdAt:new Date().toISOString(),source:'Meal plan'});}await put('plans',{...p,applied:true});await refresh();toast('Planned meals added to diary.');break;}
}}catch(err){console.error(err);toast('Could not complete action: '+(err.message||'Unknown error'));}}
async function handleSubmit(e){const form=e.target;if(!['manual-form','ai-save-form','workout-form','weight-form','goals-form','plan-form','profile-form'].includes(form.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(form));try{switch(form.id){
case 'manual-form':{const f={id:newId(),name:v.name.trim().slice(0,130),source:'Your custom food',servingG:100};for(const k of ['calories','protein','carbs','fat','fiber'])f[k]=n(v[k]);const grams=n(v.grams);if(!f.name||grams<1||grams>10000)throw Error('Enter a food name and valid grams.');await put('logs',mkLog(f,grams,v.meal));if(form.querySelector('[name=save]')?.checked)await put('foods',f);closeModal();await refresh();toast('Custom food logged.');break;}
case 'ai-save-form':{const obj={name:v.name.trim().slice(0,130)};for(const k of ['calories','protein','carbs','fat','fiber'])obj[k]=n(v[k]);if(!obj.name||obj.calories>10000)throw Error('Check your food name and calorie values.');await put('logs',addLogFromAI(obj,v.meal));closeModal();S.aiFood=null;S.photo=null;await refresh();toast('AI estimate logged.');break;}
case 'workout-form':{await put('workouts',{id:newId(),date:S.date,name:v.name.slice(0,100),minutes:n(v.minutes),calories:n(v.calories),source:'Manual'});closeModal();await refresh();toast('Workout saved.');break;}
case 'weight-form':{await put('weights',{id:newId(),date:S.date,lb:n(v.weight)});closeModal();await refresh();toast('Weight recorded.');break;}
case 'profile-form':{const input=readProfileInput(form);const result=estimatePlan(input);S.profile=input;S.profileSetup=true;await put('meta',{id:'profile',value:input});
 S.settings={...S.settings,calorieGoal:result.calorieGoal,proteinGoal:result.proteinGoal,carbsGoal:result.carbsGoal,fatGoal:result.fatGoal,exerciseBudget:false};await saveSettings();S.view='dashboard';await refresh();window.scrollTo({top:0,behavior:'instant'});toast('Your nutrition plan has been saved.');break;}

 case 'goals-form':{for(const key of ['calorieGoal','proteinGoal','carbsGoal','fatGoal','waterGoal','fastHours'])S.settings[key]=Math.max(1,Number(v[key])||DEFAULTS[key]);await saveSettings();await refresh();toast('Your goals were saved.');break;}
case 'plan-form':{const items=inDate(records('logs'),v.source);if(!items.length)throw Error('There are no foods logged on that date. Choose another day.');if(records('plans').find(x=>x.date===S.planTarget)&&!confirm('Replace the existing plan for this date?'))break;await put('plans',{id:S.planTarget,date:S.planTarget,applied:false,items:items.map(({id,date,createdAt,...rest})=>({...rest}))});closeModal();await refresh();toast('Meals planned for '+prettyDate(S.planTarget,{month:'short',day:'numeric'}));break;}
}}catch(err){console.error(err);toast(err.message||'Unable to save.');}}
async function handleChange(e){const target=e.target;try{switch(target.id){
case 'food-photo-input':{const file=target.files?.[0];if(!file)return;S.photoDesc=$('#photo-description')?.value||'';S.photo=await imageToJpeg(file);renderModal();toast('Photo selected. Run your Shortcut, then paste estimate.');break;}
case 'portion-grams':{S.grams=n(target.value);const c=$('#portion-servings');if(c)c.value=Number((S.grams/(S.food.servingG||100)).toFixed(2));const pr=$('#portion-preview');if(pr)pr.innerHTML=portionPreview(scale(S.food,S.grams));break;}
case 'portion-servings':{S.grams=n(target.value)*(S.food.servingG||100);const grams=$('#portion-grams');if(grams)grams.value=amount(S.grams,1);const pr=$('#portion-preview');if(pr)pr.innerHTML=portionPreview(scale(S.food,S.grams));break;}
case 'portion-meal':S.meal=target.value;break;
case 'exercise-budget':S.settings.exerciseBudget=target.checked;await saveSettings();render();break;
case 'theme-toggle':S.settings.theme=target.checked?'light':'dark';await saveSettings();render();break;
case 'import-file':{const file=target.files?.[0];if(!file)return;if(file.size>30*1024*1024)throw Error('Backup file is too large.');const json=JSON.parse(await file.text());if(!confirm('Restore this backup? Records with matching IDs will be replaced. Your other records will remain.'))break;await importDump(json,false);S.settings={...DEFAULTS,...(await get('meta','settings'))?.value};S.profile={...EMPTY_PROFILE,...(await get('meta','profile'))?.value};S.profileSetup=!!(await get('meta','profile'));S.fastAt=(await get('meta','fastAt'))?.value||null;await refresh();toast('Backup restored.');target.value='';break;}
}}catch(err){console.error(err);toast(err.message||'Unable to process file.');}}
function handleInput(e){const t=e.target;if(t.closest('#profile-form')){updateProfilePreview();return;}if(t.id==='food-search'){
 S.query=t.value;S.online=[];S.searchStatus='';S.productSearchSeq++;clearTimeout(S.productTimer);
 S.smartFood=estimateRestaurantMeal(S.query);S.smartSearchTried=false;
 const results=$('#modal-food-results');if(results)results.innerHTML=S.query.trim()?foodResults(matchedFoods(),'select-food'):'<div class="no-items">Enter a food to see matches.</div>';
 const hint=$('#product-status');if(hint)hint.textContent='';
 updateLiveResults();
 const query=S.query.trim();const known=rankFoodMatches(query,[...POPULAR_FOODS,...records('foods')],2);
 if(query.length>=3 && (!known.length||!!interpretFoodQuery(query).restaurant)){S.productTimer=setTimeout(()=>{if(S.query.trim()===query)void autoFindProducts(query);},620);}
}
else if(t.id==='library-search'){const v=t.value.trim().toLowerCase();const result=$('#library-results');if(result)result.innerHTML=foodResults([...records('foods'),...SEED].filter(f=>f.name.toLowerCase().includes(v)).slice(0,20),'favorite');}
else if(t.id==='ingredient-query'){S.recipeQuery=t.value;const matches=[...records('foods'),...SEED].filter(x=>x.name.toLowerCase().includes(S.recipeQuery.toLowerCase())).slice(0,6);const div=$('#ingredient-matches');if(div)div.innerHTML=matches.map(f=>`<div class="food-result"><div class="result-title"><b>${esc(f.name)}</b><small>${amount(f.calories)} kcal per 100 g</small></div><button class="round-add" data-action="recipe-add" data-id="${esc(f.id)}">+</button></div>`).join('');}
else if(t.closest('#recipe-form')){S.recipeName=$('#recipe-form [name=name]')?.value||'';S.recipeServings=Number($('#recipe-form [name=servings]')?.value)||2;}
else if(t.id==='photo-description'){S.photoDesc=t.value;}
else if(t.id==='describe-text'){S.description=t.value;}
else if(t.id==='facts-text'){S.factsText=t.value;}
else if(t.id==='facts-name'){S.factsName=t.value;}}
function handleGlobalChange(e){if(e.target.closest('#profile-form'))updateProfilePreview();if(e.target.classList.contains('recipe-grams')){S.recipeName=$('#recipe-form [name=name]')?.value||S.recipeName;S.recipeServings=Number($('#recipe-form [name=servings]')?.value)||2;const item=S.recipeIngredients[Number(e.target.dataset.recipeIndex)];if(item)item.grams=Math.max(1,n(e.target.value));renderModal();}}
async function handleStartupImport(){const params=new URLSearchParams(location.search);const text=params.get('import');if(!text)return;history.replaceState({},'',location.pathname+location.hash);if(text.length>10000){toast('Shortcut payload too large. Use manual paste.');return;}try{openModal('add','import');await acceptAIText(text);}catch(e){toast('Shortcut import error: '+e.message);}}
async function init(){try{await openApp();document.addEventListener('click',handleAction);document.addEventListener('submit',handleSubmit);document.addEventListener('input',handleInput);document.addEventListener('change',e=>{handleChange(e);handleGlobalChange(e);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)closeModal();if(e.key==='Enter'&&e.target.id==='food-search'){e.preventDefault();void autoFindProducts(S.query.trim());}});await handleStartupImport();if('serviceWorker'in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js?v=8').catch(console.warn);if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});}catch(e){console.error(e);$('#app').innerHTML=`<div class="boot"><h2>PlatePilot could not open</h2><p>IndexedDB is unavailable. Try opening the app in Safari outside Private Browsing and ensure website storage is enabled.</p><small>${esc(e.message)}</small></div>`;}}
async function openApp(){const meta=await get('meta','settings');S.settings={...DEFAULTS,...(meta?.value||{})};const profile=await get('meta','profile');S.profile={...EMPTY_PROFILE,...(profile?.value||{})};S.profileSetup=!!profile;const intro=(await get('meta','profileIntroDismissed'))?.value;if(!S.profileSetup&&!intro)S.view='profile';S.fastAt=(await get('meta','fastAt'))?.value||null;await refresh();}
init();
